def solve(inputs: dict) -> float:
    x = inputs['initial_value']
    num_steps = inputs['num_steps']

    # Keep value within 32 bits
    mask_32 = (1 << 32) - 1

    for _ in range(num_steps):
        x = x ^ ((x << 11) & mask_32)
        x = x ^ ((x >> 9) & mask_32)
        x = x ^ ((x << 15) & mask_32)
        x = x & mask_32

    return float(x)
